import * as T from './vendor/three.module.js';
import {buildForest} from './forest-world.js';
import {forestHeight,trailX} from './forest-math.js';
import {sandHeight,shoreX,Footsteps} from './journey-math.js';

function kit(root){
 const mats=new Map(),cube=new T.BoxGeometry(1,1,1),sphere=new T.SphereGeometry(1,12,8);
 const mat=(c,r=.8)=>{if(!mats.has(c))mats.set(c,new T.MeshStandardMaterial({color:c,roughness:r}));return mats.get(c)};
 const mesh=(p,g,m,x=0,y=0,z=0)=>{const o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=true;o.receiveShadow=true;p.add(o);return o};
 const box=(p,x,y,z,w,h,d,m)=>{const o=mesh(p,cube,m,x,y,z);o.scale.set(w,h,d);return o};
 const ball=(p,x,y,z,r,m,s=[1,1,1])=>{const o=mesh(p,sphere,m,x,y,z);o.scale.set(r*s[0],r*s[1],r*s[2]);return o};
 const beam=(p,a,b,r,m)=>{const v=new T.Vector3(...a),delta=new T.Vector3(...b).sub(v),o=mesh(p,new T.CylinderGeometry(r,r,delta.length(),7),m);o.position.copy(v.addScaledVector(delta,.5));o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),delta.normalize());return o};
 const tree=(p,x,y,z,s=1)=>{const g=new T.Group();p.add(g);g.position.set(x,y,z);g.scale.setScalar(s);mesh(g,new T.CylinderGeometry(.06,.17,5,8),mat('#9b9d87'),0,2.5,0);for(let j=0;j<7;j++){const a=j*2.4;beam(g,[0,2.3,0],[Math.cos(a)*.7,4.5,Math.sin(a)*.7],.035,mat('#716f56'));ball(g,Math.cos(a)*.65,4+(j%3)*.4,Math.sin(a)*.65,.8,mat(['#6d8c59','#91a66d','#b1b879'][j%3]),[1,.7,1]);}return g};
 const batch=p=>{p.updateMatrixWorld(true);const groups=new Map();p.traverse(o=>{if(!o.isMesh||o.isInstancedMesh)return;const key=o.material.uuid;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(o)});for(const list of groups.values()){if(list.length<2)continue;const vertices=[],normals=[];for(const o of list){const g=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();g.applyMatrix4(o.matrixWorld);vertices.push(...g.attributes.position.array);normals.push(...g.attributes.normal.array);o.removeFromParent();}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(vertices,3));g.setAttribute('normal',new T.Float32BufferAttribute(normals,3));const combined=new T.Mesh(g,list[0].material);combined.castShadow=true;combined.receiveShadow=true;p.add(combined);}};
 return {mat,mesh,box,ball,beam,tree,batch};
}
export function buildTrain(){
 const root=new T.Group(),inside=new T.Group();root.add(inside);const {mat,mesh,box,ball,beam,tree,batch}=kit(root),wood=mat('#9f7f59'),trim=mat('#594c3b'),cream=mat('#e3d7b8'),seat=mat('#6e7d69');
 for(let i=0;i<18;i++)box(inside,-.4,-.08,-5+i*.58,5,.12,.55,wood);
 box(inside,1.9,.35,0,.12,.7,12,cream);box(inside,1.9,2.85,0,.15,.35,12,cream);box(inside,1.9,.75,0,.25,.12,12,wood);
 for(const z of [-5,-1.9,1.9,5]){box(inside,1.84,1.87,z,.23,2.45,.14,wood);box(inside,1.7,1.87,z,.03,2.12,.19,trim);}
 box(inside,-2.1,1.5,0,.15,3.2,12,cream);box(inside,-.1,3.36,0,4.2,.14,12,cream);
 for(const z of [-3.6,2.8]){box(inside,-.7,.43,z,2.05,.24,1.18,seat);box(inside,-.7,.95,z-.5,2.05,1.05,.19,seat);for(const x of [-1.55,.15])box(inside,x,.69,z,.08,.37,1.32,wood);}
 box(inside,1,.73,-.78,1.13,.09,1.15,wood);beam(inside,[1.2,0,-.78],[1.2,.7,-.78],.05,trim);
 mesh(inside,new T.CylinderGeometry(.085,.065,.14,24),mat('#ede6d0',.3),.9,.86,-.6);const cupRing=mesh(inside,new T.TorusGeometry(.047,.013,8,20),mat('#ede6d0',.3),.8,.86,-.6);cupRing.rotation.y=Math.PI/2;mesh(inside,new T.CylinderGeometry(.072,.072,.005,24),mat('#786246',.25),.9,.933,-.6);
 box(inside,1.06,.79,-1.02,.18,.008,.33,mat('#cbb584'));for(let i=0;i<6;i++)box(inside,1.06,.796,-1.1+i*.025,.12,.003,.003,mat('#ac9c7d'));
 const steamGeo=new T.BufferGeometry(),steamArray=new Float32Array(40*3);steamGeo.setAttribute('position',new T.BufferAttribute(steamArray,3));const steam=new T.Points(steamGeo,new T.PointsMaterial({color:'#eee6d3',size:.025,transparent:true,opacity:.24,depthWrite:false}));root.add(steam);
 const terrain=new T.Mesh(new T.PlaneGeometry(600,600),mat('#a7b180'));terrain.rotation.x=-Math.PI/2;terrain.position.y=-.6;terrain.receiveShadow=true;root.add(terrain);
 const villages=new T.Group(),woods=new T.Group(),coast=new T.Group();root.add(villages,woods,coast);const movers=[];
 function moving(parent,g,z){g.userData.z=z;g.position.z=z;parent.add(g);movers.push(g)}
 for(let i=0;i<55;i++){const g=new T.Group(),x=8+(i%7)*10,z=-90+(i*23)%200;box(g,x,-.5,0,9,.04,14,mat(['#aab879','#b9bf8c','#9ba66b','#d1c48e'][i%4]));moving(villages,g,z);}
 for(let i=0;i<14;i++){const g=new T.Group(),x=17+i%4*11,z=-90+(i*37)%200;box(g,x,.65,0,2.5,2.4,2.1,mat('#dbceb0'));const shape=new T.Shape();shape.moveTo(-1.42,0);shape.lineTo(0,.86);shape.lineTo(1.42,0);shape.closePath();mesh(g,new T.ExtrudeGeometry(shape,{depth:2.45,bevelEnabled:false}),mat('#a7765d'),x,1.85,-1.22);for(let k=0;k<10;k++)for(const side of [-1,1]){const tile=box(g,x+side*.72,2.28,(k-4.5)*.25,1.66,.045,.22,mat('#a7765d'));tile.rotation.z=-side*.54;}for(const face of [-1,1])for(const xx of [-.7,.7]){box(g,x+xx,.87,face*1.07,.5,.68,.05,cream);box(g,x+xx,.87,face*1.105,.4,.56,.02,mat('#789fa3'));box(g,x+xx,.87,face*1.123,.025,.56,.025,cream);box(g,x+xx,.57,face*1.14,.59,.04,.14,wood);}box(g,x,.26,1.1,.36,.65,.06,trim);mesh(g,new T.CylinderGeometry(.11,.11,.8,8),mat('#a9a28b'),x+.75,2.4,-.5);for(let row=0;row<12;row++)box(g,x,-.36+row*.18,1.08,2.45,.015,.02,wood);tree(g,x+3,-.55,.8,.8);moving(villages,g,z);}
 for(let i=0;i<100;i++){const g=new T.Group(),x=6.5+(i%10)*6.5,z=-90+(i*37)%200;tree(g,x,-.6,0,.8+(i%5)*.22);moving(woods,g,z);}
 const seaGeo=new T.PlaneGeometry(450,400);seaGeo.rotateX(-Math.PI/2);const sea=mesh(coast,seaGeo,new T.MeshStandardMaterial({color:'#7da9ac',roughness:.23,metalness:.22}),235,-.5,0);sea.castShadow=false;
 for(let i=0;i<36;i++){const g=new T.Group(),z=-90+(i*29)%200;ball(g,8+(i%3)*2,-.52,0,.4,mat('#a8aa94'),[2,.7,1]);if(i%3===0)tree(g,9,-.5,0,.75);moving(coast,g,z);}
 const hills=new T.Group();root.add(hills);for(let layer=0;layer<2;layer++){const g=new T.PlaneGeometry(260,90,90,1),p=g.attributes.position;for(let i=0;i<p.count;i++){const u=p.getX(i);p.setY(i,p.getY(i)>0?13+Math.sin(u*.033+layer)*9+Math.sin(u*.077)*4:-1);}g.computeVertexNormals();const m=new T.Mesh(g,new T.MeshBasicMaterial({color:layer?'#91a99a':'#7e9b8b',side:T.DoubleSide,fog:true}));m.rotation.y=Math.PI/2;m.position.x=90+layer*35;hills.add(m);}
 // Foreground poles give a clear sense of travel and parallax.
 const poles=new T.Group();root.add(poles);for(let i=0;i<8;i++){const g=new T.Group();beam(g,[4,-.6,0],[4,5.2,0],.065,mat('#8b8b75'));beam(g,[3.45,4.75,0],[4.55,4.75,0],.045,trim);moving(poles,g,-90+i*27);}
 for(const p of [villages,woods,coast]){const repeat=p.clone(true);repeat.position.z=100;p.add(repeat);batch(p)}batch(inside);
 function update(t,route){const phase=route<.36?0:route<.7?1:2;villages.visible=phase===0;woods.visible=phase===1;coast.visible=phase===2;hills.visible=phase!==2;terrain.material.color.set(phase===2?'#c7c4a1':'#a7b180');for(const p of [villages,woods,coast])p.position.z=-(t*3.2%100);for(const g of movers)g.position.z=((g.userData.z-t*3.2+100)%210+210)%210-100;
  const a=steamGeo.attributes.position;for(let i=0;i<40;i++){const f=((t*.28+i/40)%1);a.setXYZ(i,.9+Math.sin(i+t)*f*.05,.96+f*.42,-.6+Math.cos(i+t)*f*.04)}a.needsUpdate=true;return phase;
 }
 return {root,update};
}
export function buildWalkingForest(){
 const base=buildForest(),root=base.root,decor=new T.Group();root.add(decor);const {mat,mesh,box,ball,beam,batch}=kit(root),birds=[],rabbits=[],butterflies=[];
 // Keep a detailed local forest around this short walking route.
 const matrix=new T.Matrix4(),point=new T.Vector3(),tint=new T.Color();base.root.traverse(o=>{if(!o.isInstancedMesh||o.count<50)return;let n=0;const count=o.count;for(let i=0;i<count;i++){o.getMatrixAt(i,matrix);point.setFromMatrixPosition(matrix);if(Math.abs(point.x)>34||point.z< -57||point.z>24)continue;o.setMatrixAt(n,matrix);if(o.instanceColor){o.getColorAt(i,tint);o.setColorAt(n,tint)}n++;}o.count=n;o.instanceMatrix.needsUpdate=true;if(o.instanceColor)o.instanceColor.needsUpdate=true;});
 // Low wildflowers at the edge of the trail, each with stem, leaves and a small heart.
 for(let i=0;i<210;i++){const z=-35+(i%30)*.48,x=trailX(z)+(i%2?1:-1)*(1.45+(i%7)*.13),y=forestHeight(x,z);const g=new T.Group();g.position.set(x,y,z);decor.add(g);const h=.15+(i%4)*.045;beam(g,[0,0,0],[0,h,0],.008,mat('#73895b'));for(let j=0;j<5;j++){const a=j*Math.PI*.4;ball(g,Math.cos(a)*.035,h,Math.sin(a)*.035,.033,mat(['#e8d5a2','#c8b7d1','#dfb5b1'][i%3]),[1,.35,1]);}ball(g,0,h+.005,0,.016,mat('#c5a667'));box(g,.025,h*.45,0,.07,.012,.025,mat('#7a925d'));}
 for(let i=0;i<6;i++){const g=new T.Group();root.add(g);const m=mat(i%2?'#87988c':'#a39477');ball(g,0,0,0,.068,m,[1.5,1,.8]);ball(g,.07,.04,0,.04,m);const beak=mesh(g,new T.ConeGeometry(.014,.045,5),mat('#c0a369'),.12,.04,0);beak.rotation.z=-Math.PI/2;ball(g,.085,.05,.029,.005,mat('#263b33'));const wings=[];for(const s of [-1,1])wings.push(ball(g,-.02,.005,s*.055,.065,m,[1.2,.22,.7]));birds.push({g,wings,x:trailX(-24)+1.8+(i%2)*.7,z:-25+(i%3)*1.2,phase:i*1.6});}
 for(let i=0;i<3;i++){const g=new T.Group();root.add(g);const fur=mat(i?'#c2b299':'#ab9274');ball(g,0,.16,0,.14,fur,[1.25,1,.8]);ball(g,.13,.23,0,.085,fur);for(const side of [-1,1]){const e=ball(g,.12,.36,side*.035,.055,fur,[.6,2,.5]);e.rotation.z=-.17;ball(g,.19,.25,side*.055,.008,mat('#344538'));ball(g,-.05,.055,side*.09,.05,fur,[1.5,.5,.8]);}ball(g,-.17,.18,0,.045,mat('#e6ddcb'));rabbits.push({g,x:trailX(-20)+1.7+i*.38,z:-20+i*.65,phase:i*2});}
 // A squirrel with an arched tail sits close to the flowers.
 const squirrel=new T.Group();root.add(squirrel);const fur=mat('#a58161');ball(squirrel,0,.15,0,.11,fur,[1,1.5,.7]);ball(squirrel,.04,.31,0,.068,fur);for(const s of [-1,1]){ball(squirrel,.04,.37,s*.035,.027,fur,[.8,1.6,.7]);ball(squirrel,.08,.32,s*.05,.008,mat('#293b32'));}const tail=ball(squirrel,-.13,.22,0,.12,fur,[.7,1.8,.7]);tail.rotation.z=-.45;
 for(let i=0;i<13;i++){const g=new T.Group();root.add(g);const wings=[];for(const s of [-1,1]){const w=mesh(g,new T.CircleGeometry(.045,10),new T.MeshStandardMaterial({color:i%2?'#d5bd83':'#c4b4d1',side:T.DoubleSide}),s*.035,0,0);w.rotation.x=Math.PI/2;wings.push(w)}butterflies.push({g,wings,phase:i*1.7});}
 batch(decor);
 function update(t){base.update(t,'dawn');for(const b of birds){const fly=Math.sin(t*.17+b.phase)>.4,x=b.x+(fly?Math.sin(t*.8+b.phase)*.9:0),z=b.z+(fly?Math.cos(t*.6+b.phase)*.7:0);b.g.position.set(x,forestHeight(x,z)+(fly?1.5+Math.sin(t)*.15:.85),z);b.g.rotation.y=fly?t*.3+b.phase:b.phase;b.wings.forEach((w,i)=>w.rotation.x=(i?1:-1)*(fly?Math.sin(t*15+b.phase)*1.1:.1));}
  for(const r of rabbits){const hop=Math.max(0,Math.sin(t*.8+r.phase));r.g.position.set(r.x+Math.sin(t*.12+r.phase)*.2,forestHeight(r.x,r.z)+hop*.07,r.z);r.g.rotation.y=Math.PI+Math.sin(t*.3+r.phase)*.16;}
  squirrel.position.set(trailX(-27)+1.6,forestHeight(trailX(-27)+1.6,-27),-27);squirrel.rotation.y=Math.PI+Math.sin(t*.6)*.1;
  butterflies.forEach((b,i)=>{const z=-32+(i%8)*1.3+Math.sin(t*.45+b.phase)*.25,x=trailX(z)+1.5+Math.cos(t*.5+b.phase)*.5;b.g.position.set(x,forestHeight(x,z)+.45+Math.sin(t+b.phase)*.15,z);b.g.rotation.y=t*.4+b.phase;b.wings.forEach((w,j)=>w.rotation.y=(j?1:-1)*Math.sin(t*8+b.phase)*.8);});
 }
 return {root,update,colliders:base.colliders,focus:{flowers:{x:trailX(-30)-.35,z:-30,yaw:-1.05,pitch:-.55},birds:{x:trailX(-24),z:-24,yaw:-1.2,pitch:-.22},animals:{x:trailX(-20),z:-20,yaw:-1.25,pitch:-.5}}};
}
export function buildBeach(){
 const root=new T.Group(),fixed=new T.Group();root.add(fixed);const {mat,mesh,box,ball,beam,batch}=kit(root),footsteps=new Footsteps();let seed=102;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};
 const geo=new T.PlaneGeometry(100,210,100,180);geo.rotateX(-Math.PI/2);const p=geo.attributes.position,colors=new Float32Array(p.count*3),sand=new T.Color('#d6c7a7'),wet=new T.Color('#b5b39e');for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i);p.setY(i,sandHeight(x,z));const c=sand.clone().lerp(wet,Math.max(0,Math.min(1,(3-x)/5))).multiplyScalar(.97+rand()*.055);colors.set([c.r,c.g,c.b],i*3)}geo.setAttribute('color',new T.BufferAttribute(colors,3));geo.computeVertexNormals();mesh(fixed,geo,new T.MeshStandardMaterial({vertexColors:true,roughness:.95}));
 const time={value:0};const waterMat=new T.ShaderMaterial({uniforms:{time},transparent:true,depthWrite:false,side:T.DoubleSide,vertexShader:`uniform float time;varying vec3 p;void main(){p=(modelMatrix*vec4(position,1.)).xyz;p.y=.13+sin(p.x*1.8-time*.9+p.z*.05)*.045+sin(p.x*.7-time*.5)*.035;gl_Position=projectionMatrix*viewMatrix*vec4(p,1.);}`,fragmentShader:`uniform float time;varying vec3 p;void main(){float shore=-2.+sin(p.z*.09)*.55;float front=shore+2.2+sin(time*.42+p.z*.09)*.8;if(p.x>front)discard;float depth=clamp((front-p.x)/12.,0.,1.);float ridge=sin(p.x*2.5-time*.9+p.z*.05);float lace=.75+.25*sin(p.z*22.+sin(p.x*27.));float foam=(1.-smoothstep(.02,.22,abs(p.x-front)))*lace;float small=pow(max(0.,ridge),18.)*.12;vec3 c=mix(vec3(.60,.75,.71),vec3(.19,.43,.50),depth);c=mix(c,vec3(.94,.96,.87),clamp(foam+small,0.,1.));float a=mix(.28,.99,smoothstep(0.,.9,depth))+foam*.55;gl_FragColor=vec4(c,a);\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}`});const wg=new T.PlaneGeometry(200,230,200,140);wg.rotateX(-Math.PI/2);wg.translate(-75,0,0);const water=new T.Mesh(wg,waterMat);root.add(water);
 const gulls=[];for(let i=0;i<12;i++){const g=new T.Group();root.add(g);ball(g,0,0,0,.09,mat('#e7e7d6'),[1.6,.7,.7]);ball(g,.12,.025,0,.04,mat('#ecead8'));const wings=[];for(const s of [-1,1])wings.push(box(g,0,0,s*.16,.06,.018,.36,mat('#d4d9cd')));gulls.push({g,wings,phase:i*1.3});}
 for(let i=0;i<160;i++){const x=3.5+rand()*18,z=-45+rand()*95,r=.018+rand()*.06;const o=ball(fixed,x,sandHeight(x,z)+r*.15,z,r,mat(['#b0a995','#c6bfaa','#ddd6c1'][i%3]),[1.4,.35,1]);o.rotation.y=rand()*6.28;if(i%5===0)for(let j=0;j<4;j++)beam(fixed,[x,sandHeight(x,z),z],[x+Math.sin(j)*.06,sandHeight(x,z)+.35+rand()*.15,z+Math.cos(j)*.05],.009,mat('#9ca17a'));}
 for(let i=0;i<32;i++){const x=.3+rand()*3.5,z=-30+rand()*65;const g=mesh(fixed,new T.SphereGeometry(.045,10,5,0,Math.PI*2,0,Math.PI/2),mat('#e2d7be'),x,sandHeight(x,z)+.01,z);g.scale.set(1,.3,.8);g.rotation.y=rand()*6.28;}
 beam(fixed,[4,sandHeight(4,2)+.09,2],[6,sandHeight(6,2)+.09,2.8],.12,mat('#a09479'));for(const s of [-1,1]){box(fixed,7+s*.8,sandHeight(7,8)+.23,8,.12,.5,.5,mat('#938268'));}box(fixed,7,sandHeight(7,8)+.47,8,2.1,.12,.56,mat('#a18e6c'));box(fixed,7,sandHeight(7,8)+.88,8.23,2.1,.55,.07,mat('#a18e6c'));
 batch(fixed);
 // One instanced decal mesh, with an individual fading footprint for every real footfall.
 const footGeo=new T.PlaneGeometry(.185,.36);footGeo.rotateX(Math.PI/2);footGeo.setAttribute('fade',new T.InstancedBufferAttribute(new Float32Array(96),1));
 const footMat=new T.ShaderMaterial({uniforms:{},transparent:true,depthWrite:false,side:T.DoubleSide,vertexShader:`attribute float fade;varying vec2 st;varying float alpha;void main(){st=uv;alpha=fade;vec4 p=modelMatrix*instanceMatrix*vec4(position,1.);float shore=-2.+sin(p.z*.09)*.55;p.y=.07+max(-1.4,p.x-shore-1.9)*.13+.009;gl_Position=projectionMatrix*viewMatrix*p;}`,fragmentShader:`varying vec2 st;varying float alpha;float oval(vec2 p,vec2 c,vec2 s){return exp(-dot((p-c)/s,(p-c)/s)*2.); }void main(){float f=max(oval(st,vec2(.49,.27),vec2(.3,.30)),oval(st,vec2(.5,.58),vec2(.43,.35)));for(int i=0;i<5;i++){float j=float(i);f=max(f,oval(st,vec2(.2+j*.145,.82+sin(j*.65)*.055),vec2(.1,.11)));}float a=smoothstep(.08,.38,f)*alpha*.48;if(a<.005)discard;vec3 c=mix(vec3(.18,.13,.08),vec3(.55,.46,.32),smoothstep(.1,.25,f)*(1.-smoothstep(.25,.55,f))*.5);gl_FragColor=vec4(c,a);\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}`});const prints=new T.InstancedMesh(footGeo,footMat,96);prints.count=0;prints.frustumCulled=false;root.add(prints);const dummy=new T.Object3D();
 function update(t,dt){time.value=t;footsteps.wash(t,dt);prints.count=footsteps.items.length;footsteps.items.forEach((f,i)=>{dummy.position.set(f.x,0,f.z);dummy.rotation.set(0,f.yaw,0);dummy.scale.set(f.side,1,1);dummy.updateMatrix();prints.setMatrixAt(i,dummy.matrix);footGeo.attributes.fade.setX(i,f.fade);});prints.instanceMatrix.needsUpdate=true;footGeo.attributes.fade.needsUpdate=true;
  for(const b of gulls){const a=t*.12+b.phase;b.g.position.set(-7+Math.cos(a)*7,4+Math.sin(a*1.4)*.7,Math.sin(a)*16+4);b.g.rotation.y=-a;b.wings.forEach((w,i)=>w.rotation.x=(i?1:-1)*(.12+Math.sin(t*3+b.phase)*.2));}
 }
 return {root,update,footsteps};
}
